/bin/bash -lc "python - <<'PY'
import json, urllib.request, urllib.parse
base='https://quay.io/api/v1/repository/biocontainers/anndata/tag/'
params={'limit':'100'}
seen=0
for page in range(20):
    url=base+'?'+urllib.parse.urlencode(params)
    with urllib.request.urlopen(url, timeout=30) as r: data=json.load(r)
    tags=data.get('tags',[])
    seen+=len(tags)
    for t in tags:
        n=t['name']
        if n.startswith(('0.7','0.8','0.9','0.10','0.11')):
            print(n, t.get('manifest_digest'))
    if not data.get('has_additional'):
        break
    # quay pagination uses next_page token
    token=data.get('page') or data.get('next_page')
    print('PAGE', page, 'seen', seen, 'keys', data.keys(), 'next', token)
    if token:
        params={'limit':'100','page':token}
    else:
        last=tags[-1]['name'] if tags else ''
        params={'limit':'100','page':last}
PY"

